**Match with quarterly earnings announcement file: (start with COMPUSTAT and overlap with IBES);
	proc sql;
		create table announce_compustat as
		select distinct a.*, b.fqtr, b.datadate, b.rdq, b.prccq, b.cshoq, b.mcap, b.saleq
		from firm as a, (select distinct gvkey, fyearq, datadate, fqtr, rdq, cshoq, prccq, cshoq*prccq as mcap, saleq 
