*match with CRSP PERMNOs;
proc sql;
	create table firm as 
	select distinct b.lpermno as permno, a.*
	from firm as a, crsp.ccmxpf_lnkhist as b
	where linktype in ("LC", "LU", "LS", "LX", "LD", "LN", "LO") /*and usedflag = 1*/
	and not missing(lpermno) and a.gvkey=b.gvkey 
	and (linkdt <= datadate or linkdt = .B) and (datadate <= linkenddt or linkenddt= .E);
quit;

*Prior 16 quarters for estimation: each firm-quarter must have at least 14 previous quarters of data ;
proc sql;
	create table temp as 
	select distinct a.*, b.fqenddt, b.dnibe, b.bhr , year(a.datadate1) as year, count(b.fqenddt) as nqtr
	from temp (rename=(gvkey = gvkey1 permno = permno1 datadate = datadate1 fqenddt = fqenddt1 datacqtr = datacqtr1 )) as a, 
		 firm as b
	where a.gvkey1 = b.gvkey and a.permno1=b.permno
	and intnx('quarter', a.fqenddt1, -15, 'beginning') <= b.fqenddt and b.fqenddt<= a.fqenddt1 
	group by gvkey1, permno1, datadate1, fqenddt1
	having nmiss(dnibe, bhr)=0  and 14<=calculated nqtr<=16  
	order by gvkey1, permno1, datadate1, fqenddt1 ;

data temp; merge temp est;  by gvkey1 datadate1 fqenddt1; 
	where &begdate <= datadate1 <= &enddate;
	if nmiss(a_i, b_i) = 0 ;
run;

	proc sql;
		/*retrieve CRSP cumulative adjustment factor for IBES report and estimate dates*/
        create table adjfactor as
        select distinct a.*
        from crsp.dsf (keep=permno date prc cfacshr ) as a, (select distinct permno from ibes_estimate) as b
        where a.permno=b.permno and &begdate<=a.date and a.date<=&enddate ;

		/*if adjustment factors are not the same, adjust the estimate to be on the same basis with the actual   */
		create table ibes_estimate as
		select distinct a.*, abs(b.prc) as prc_act , b.cfacshr as adjfac_act
		from ibes_estimate as a, adjfactor as b
		where a.permno= b.permno and intnx("week", a.repdats , -1 , 'b') <= b.date and b.date <= a.repdats
		group by a.ticker , a.pends , a.repdats

**shift weekend EAD forward to next trading day; 
proc sql;
	create table EAD 
   	as select a.*, b.caldt as EAD1 format date9. "Closest Trading Day" 
   	from EAD as a left join crsp.dsix (keep=caldt) as b
   	on b.caldt - a.EAD>=0 and b.caldt - a.EAD<=7
	group by permno, EAD
  	having (b.caldt - a.EAD)=min(b.caldt - a.EAD);
quit;

data EAD(drop=EAD1); set EAD; if EAD1 > EAD then EAD=EAD1; else EAD=EAD; run;

**Add CRSP returns;
rsubmit;
	proc sql;
		create table return as
		select *
		from (select permno, date, intnx("quarter", date, 0, "end") as yrqtr format date9. , ret, vol, shrout, 
					 count(distinct date) as td_firm, exp(sum(log(1+ret))) - 1 as qret "Focal Firm Qtr Return" ,
					 sum(vol) as qvol "Focal Firm Qtr Volume" 
			  from crsp.dsf where nmiss(ret, vol)=0 and vol>= 0 /*missing trading volume is recorded as -99: see WRDS manual*/
				and intnx("quarter", &begdate, -2, "b")<=date and date<=intnx("quarter", &enddate, 2, "e")
			    group by permno, intnx("quarter", date, 0)) as a ,

			  /*using value-weighted return as market return here*/
			 (select caldt, vwretd, count(distinct caldt) as td_mkt, exp(sum(log(1+vwretd))) - 1 as qmktret "Market Qtr Return"
			  from crsp.dsix where not missing(vwretd) 
				and intnx("quarter", &begdate, -2, "b")<=caldt and caldt<=intnx("quarter", &enddate, 2, "e") 
				group by intnx("quarter", caldt, 0)) as b
		where a.date=b.caldt;

		**delisting returns;
		create table return(drop=ret1) as
		select a.*, (1+a.ret1)*sum(1,b.dlret)-1 as ret "Ret adjusted for delisting"
		from return(rename=(ret=ret1)) as a left join crsp.dsedelist(where=(missing(dlret)=0)) as b
		on a.permno=b.permno and a.date=b.dlstdt
		order by a.permno, a.date; 
	quit;


	**drop ADRs, keep ordinary shares only;
	proc sql;
		create table return as 
		select distinct a.*  
		from return as a, (select distinct permno, shrcd, min(namedt) as mindate, max(nameenddt) as maxdate
 						  from crsp.stocknames where shrcd in (10,11)  group by permno, shrcd) as b 
		where a.permno=b.permno and b.mindate<=a.date and a.date<=b.maxdate ;
	quit;

