*CRSP market value of equity at the beginning-of-period (quarter);
proc sql;
	create table firm as 
	select	distinct a.*, b.prc, b.shrout
	from firm as a left join crsp.msf as b
	on a.permno = b.permno 
	and intnx('month', fqenddt, -3, 'end') = intnx('month', b.date, 0, 'end') ;
quit;

data firm; set firm;
	if not missing(prc) and shrout > 0 then bmve = (abs(prc)*shrout) / 1000; /* shrout is in thousands. so bmve is in millions now. */
	drop prc shrout ;
run;

*CRSP stock return during the quarter (i.e. buy-and-hold return);
proc sql;
	create table firm as 
	select distinct a.*, b.ret, b.date
	from firm as a left join crsp.msf as b
	on a.permno = b.permno 
	and intnx('month', a.fqenddt, -2, 'beginning') < b.date and b.date<= a.fqenddt
	order by gvkey, datadate, fqenddt, date	;

	create table firm(drop=ret date n) as
	select distinct * , exp(sum(log(1 + ret))) -1 as bhr , count(ret) as n
	from firm
	group by gvkey, datadate, fqenddt 
	having calculated n = 3 ; *each quarter must contain three obs of monthly stock returns;
quit;

**detour to calculate EARNINGS SURPRISE for later use;
rsubmit;
	proc sql; 
		create table tickers as
		select distinct ticker
		from announce_ibes where not missing(ticker);

		create table ibes_estimate(drop=measure fpi usfirm report_curr) as
        select distinct b.*
        from tickers as a,
			 (select distinct ticker, fpedats, estimator, analys, anndats, actdats,pdf, value, measure, fpi, usfirm, report_curr
			         from ibes.detu_epsus where &begdate<=fpedats<=&enddate and measure='EPS' and fpi in ('6','7') and usfirm=1 
		                           and report_curr="USD" and anndats<=actdats and nmiss(anndats, value)=0) as b                                                          
        where a.ticker=b.ticker

data firm(keep=conm gvkey fyear datadate sich fyr); set comp.funda;
	where indfmt='INDL' and datafmt='STD' and consol='C' and popsrc='D' 
	and year(&begdate)-4 <= fyear and fyear<=year(&enddate) /*and fyr=12*/ and not missing(sich);
run;
proc sort data=firm nodupkey; by gvkey fyear; run;

*Compustat quarterly data;
proc sql;
	create table firm as
	select distinct a.*, b.datadate as fqenddt, b.datacqtr, b.ibq as nibe 
	from firm as a , (select distinct gvkey, fyearq, datadate, datacqtr, ibq from comp.fundq) as b
	where a.gvkey=b.gvkey and a.fyear=b.fyearq 
	and intnx('month', a.datadate, -11, 'beginning') <= b.datadate and b.datadate <=a.datadate
	order by a.gvkey, a.datadate;
quit;

**combine Compustat and IBES earnings announcement files and select the first reported date; 
rsubmit;
	proc sql;
		create table EAD as
		select distinct *
		from announce_compustat as a , announce_ibes(drop=measure pdicity fyear fqtr nqtr comnam) as b
		where a.gvkey=b.gvkey  
		/*and a.rdq=b.anndats*/
		and intnx("quarter", a.datadate, 0, "end")=intnx("quarter", b.pends, 0, "end")
		and intnx("month", a.rdq, 0, "end")=intnx("month", b.anndats, 0, "end")
		;
	quit;

	data EAD; set EAD; 
		**drop obs with more than five days difference between reported EADs, see DellaVigna & Pollet (2009JF); 
		if abs(rdq-anndats)<=5; 

		if rdq=anndats then agree=1; else agree=0; /*96% of times agree*/
		diff=rdq-anndats; 

		**select the first EAD as true EAD, see Smith & So (2022JAR);
		if agree=1 then EAD=rdq; else EAD=min(rdq, anndats);

		**adjust for after-hours announcement (next trading day), see Beaver et al (2020JAE);
		if EAD=anndats and 2<=weekday(anndats)<=6 and hour(anntims)>=16 then EAD=intnx('day',anndats,+1); 

		format EAD date9.;
	run;

**must have one first-announcer per industry-year-quarter;
data EAD1; set EAD; where permno=permno1; run;
proc sort data=EAD1 nodupkey; by &industry fyear fqtr; run;

rsubmit;	
	proc sql;
		create table EAD_return as
		select a.*, b.ret as ret_f, b.vol as vol_f, b.volturn as vol_f_scaled 
		from EAD2 as a left join return as b
		on a.permno_f=b.permno and a.date=b.date;

		create table EAD_return as
		select a.*, b.ret as ret_p, b.vol as vol_p, b.volturn as vol_p_scaled
		from EAD_return as a left join return as b
		on a.permno_p=b.permno and a.date=b.date;


		create table EAD_return as
		select a.*, b.cum3dayret as ret3d_p,  b.cum3dayvwretd, /*3-day moving cumulative return for peers on non-EAD*/
					b.cum3dayret_v2 as ret3d_p_ead, b.cum3dayvwretd_v2 as vwretd3d_ead /*3-day [0,+2] cumulative return for peers  on focal EAD*/
		from EAD_return as a left join return2 as b
		on a.permno_p=b.permno and a.date=b.date
		order by a.&industry, a.fyear, a.permno_p, a.EAD1, a.date ;

**must have common trading day;
	data EAD_return_clean; set EAD_return; 
		if nmiss(ret_f, ret_p)=0; 

		if EAD1=date then ret3d_p = ret3d_p_ead; else ret3d_p = ret3d_p;
		if EAD1=date then cum3dayvwretd = vwretd3d_ead; else cum3dayvwretd = cum3dayvwretd;
		if 1<=(date-EAD1)<=4 then ret3d_p =.; else ret3d_p=ret3d_p;
		if 1<=(date-EAD1)<=4 then cum3dayvwretd =.; else cum3dayvwretd=cum3dayvwretd;
	run;

*Loop by firm &i for year &year. This will generate a dataset of firm i-j AcctComp for each year;
	%macro loop(year, nfirms); 
		data temp1; set temp; if year(datadate1)=&year;
		proc sort; by gvkey1 ;

		data nfirms; set temp1; keep gvkey1;
		proc sort nodupkey; by gvkey1;

		data nfirms; set nfirms; id = _N_;

		data temp1; merge temp1 nfirms; by gvkey1;

%do i= 1 %to &nfirms;

	data est1; set temp1;
	proc sort nodupkey; by gvkey1;

	data est2; set temp1; if id = &i; 

	*form firm i-j pairs;
	proc sql;
		create table est2 as 
		select a.*, b.gvkey1 as gvkey_j, b.permno1 as permno_j, b.a_i as a_j, b.b_i as b_j
		from est2 as a left join est1 as b
		on a.gvkey1 ne b.gvkey1	and a.permno1 ne b.permno1 and a.sich = b.sich;	
	quit;

	*calculate estimation error (i.e. difference) between pair firm-specific accounting system estimated above;
	data est2; set est2;
		a_dif = a_i - a_j;
		b_dif = b_i - b_j;
		error = ABS(a_dif + bhr * b_dif);
	drop a_i a_j b_i b_j;

	/*proc sort data=est2; by gvkey1 datadate1 fqenddt1 datacqtr1 gvkey_j fqenddt;*/
	proc sort data=est2; by gvkey1 permno1 datadate1 gvkey_j permno_j fqenddt;

	*mean error between firm i-j pairs;
	proc univariate noprint; by gvkey1 permno1 datadate1 gvkey_j permno_j;
		var error ;
		output out = univ n=n mean = me_error ; 

	*comparability measure;
	data univ; set univ; 
		acctcomp = -1 * me_error*100;
		acctcomp = round(acctcomp, 0.001);
		rename gvkey1 = gvkey_i;
		rename permno1 = permno_i;
		rename datadate1 = datadate_i;

		if not missing (acctcomp);
		if 14 <= n <= 16;

		drop me_error n;

	proc append base = final data = univ; run;
%end ;

/* DATA= must be specified and data set must exist */
%if &data= or %sysfunc(exist(&data)) ne 1 %then %do;
  %put ERROR: DATA= data set not specified or not found.;
  %goto exit;
%end;

%if &chk=1 %then %do;
  %put ERROR: Predicted values from both models must exist in every observation.;
  %goto exit;
%end;

/* Verify response is binary if DIST1 or DIST2 is BIN and not events/trials */
%if (&dist1=BIN or &dist2=BIN) and &trials= %then %do;
   ods exclude all;
   ods output nlevels=_nlvls;
   proc freq data=&data nlevels;
    where missing(&response) ne 1;
    table &response;
    run;
   ods select all;
   data _null_;
    set _nlvls;
    call symput ("nlvls",nlevels);
    run;
   %if &nlvls ne 2 %then %do;
    %put ERROR: Binomial response variable, &response, must have exactly two levels.;
    %goto exit;
   %end;
%end;

proc sql;
 reset noprint;

 /* If have only one probability in an observation, then response data is
    not the same for the two models and tests cannot be done.
 */
 select
   sum( ((&p1 is missing) and (&p2 is not missing)) or
        ((&p1 is not missing) and (&p2 is missing)) ) as _chk
   into :chk
   from &data;

 /* Compute probability of response for specified distribution for each model */
 create table _m(drop=_n _BINresp) as
 select 
   count(&p1) as _n, 
   %if &freq ne %then sum(&freq) as _sumf,;

/* Compute components of Vuong statistics and Clarke statistics and p-values */
ods exclude all;
proc univariate data=_m vardef=n; 
 %if &nparm1 ne and &nparm2 ne %then %do;
   var _m _mA _mS _l1 _l2; 
   output out=_VC 
        sum=sumM sumMA sumMS LL1 LL2 n=n std=stdm 
        msign=signM signMA signMS probm=prsignM prsignMA prsignMS;
 %end;
 %else %do;
   var _m _l1 _l2; 
   output out=_VC 
        sum=sumM LL1 LL2 n=n std=stdm 
        msign=signM probm=prsignM;
 %end;
 run;

/* Display header table with data and model information */
title "The Vuong Macro";
title2 " ";
data _head;
  if _n_=1 then set _VC;
  length item $40 value $40;

  item="Data Set"; value="&data"; output;
  item="Response"; value="&response"; output;

**select a random day return for peers;
	proc sort data=EAD_ret_vol_sich10(where=(ead1 ne date)) out=eadret; by permno_p fyear fqtr; run;
