	   	strata permno_p fyear fqtr;
	run;


	proc sql;
		create table EAD_ret_vol_sich10 as
		select a.*, b.ret_p as randret_p
		from  EAD_ret_vol_sich10 as a, randsamp as b
		where a.permno_p=b.permno_p and  a.fyear=b.fyear and a.fqtr=b.fqtr;
	quit;


/**************************************************************************
TABLE 8 Panel A: Average R2 comparison to benchmark R2 (1/63): 
		  		(a)perform T-TEST 
		  		(b)perform VUONG TEST
for Vuong test step by step SAS instructions, see https://support.sas.com/kb/42/514.html 
***************************************************************************/
	data vuong; set EAD_ret_vol_sich10; where ead1 = date; run;
	proc sort data=vuong; by fyear; run;
	proc reg data=vuong outest=outest plots=none noprint;
		by fyear;
		model r_peer_qtr = ret_p / rmse rsquare adjrsq ;
		model r_peer_qtr = randret_p / rmse rsquare adjrsq ;
	run;

**VUONG TEST;
proc reg data=vuong ;
	model r_peer_qtr = ret_p /rmse ; /*check ODS output in the result viewer for RMSE, to be used as scale1 in the macro below*/
	output out=vuong pred=pred_ret1 ;
run; quit;

proc reg data=vuong ;
	model r_peer_qtr = randret_p /rmse ; /*check ODS output in the result viewer for RMSE, to be used as scale2 in the macro below*/
	output out=vuong pred=pred_ret2;
run; quit;

