	data ibes_estimate; set ibes_estimate;
        by ticker fpedats estimator analys anndats;
        if last.analys;
	run;
	/*link unadjusted estimates with unadjusted actuals and CRSP permnos */
	proc sql;
		create table ibes_estimate as
		select distinct a.*, b.pends, b.anndats as repdats, b.actual, b.permno
		from ibes_estimate as a, (select distinct ticker, pends, permno, anndats, actual from announce_ibes) as b 
		where a.ticker=b.ticker and a.fpedats=b.pends
		having nmiss(repdats, anndats)=0 and 0<intck('day',anndats,repdats)<=90 ;
	quit;

	proc sql;
		/*retrieve CRSP cumulative adjustment factor for IBES report and estimate dates*/
        create table adjfactor as
        select distinct a.*
        from crsp.dsf (keep=permno date prc cfacshr ) as a, (select distinct permno from ibes_estimate) as b
        where a.permno=b.permno and &begdate<=a.date and a.date<=&enddate ;

		/*if adjustment factors are not the same, adjust the estimate to be on the same basis with the actual   */
		create table ibes_estimate as
		select distinct a.*, abs(b.prc) as prc_act , b.cfacshr as adjfac_act
		from ibes_estimate as a, adjfactor as b
		where a.permno= b.permno and intnx("week", a.repdats , -1 , 'b') <= b.date and b.date <= a.repdats
		group by a.ticker , a.pends , a.repdats
		having abs(a.repdats - b.date) = min(abs(a.repdats - b.date))
		order by a.ticker , a.pends , a.repdats;

		create table ibes_estimate as
		select distinct a.* , b.cfacshr as adjfac_est
		from ibes_estimate as a , adjfactor as b
		where a.permno = b.permno and intnx("week" , a.anndats , -1 , 'b') <= b.date and b.date <= a.anndats
		group by a.ticker , a.fpedats , a.estimator , a.analys , a.anndats
		having abs(a.anndats - b.date) eq min(abs(a.anndats - b.date))
		order by a.ticker , a.fpedats , a.estimator , a.analys , a.anndats ;
    quit;
	data ibes_estimate; set ibes_estimate; 
		if adjfac_est eq 0 then adjfac_est = 1;
		if adjfac_act eq 0 then adjfac_act = 1;
		estval_adj = value * coalesce(adjfac_act / adjfac_est , 1); /*adjusted estimate value*/
		drop adjfac: ;
	run;

	**trading volume scaled by shares outstanding;
	data return; set return; 
		volturn = vol/(shrout*1000); /*no of shares outstanding is recorded in units of 1,000*/
	run; 

	/*calculate 3-day moving cumulative return*/
	proc expand data=return out=return2 method=none;
	    by permno;
    	convert ret=cum3dayret / transformout=(+1 nomiss movprod 3 -1 trimleft 2);
		convert vwretd=cum3dayvwretd / transformout=(+1 nomiss movprod 3 -1 trimleft 2);

		convert ret=cum3dayret_v2 / transformout=(+1 nomiss movprod 3 -1 trimleft 2 lead 2);
		convert vwretd=cum3dayvwretd_v2 / transformout=(+1 nomiss movprod 3 -1 trimleft 2 lead 2);
	run; quit;
